function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 2 || s.length > 100) return 's needs 2 to 100 characters.';
  if (!/^[a-z][a-z2-9]*$/.test(s)) return 's starts with a lowercase letter and uses only lowercase letters and digits 2 to 9.';
  if (!Number.isInteger(k) || k < 1 || k > 1000000000) return 'k is a whole number from 1 to 10^9.';
  let length = 0n;
  for (const ch of s) length = ch >= '2' && ch <= '9' ? length * BigInt(ch) : length + 1n;
  if (length >= 2n ** 63n) return 'The decoded tape must have fewer than 2^63 letters.';
  if (BigInt(k) > length) return 'k must not be larger than the decoded tape.';
  return null;
}

