function decodeAtIndex(s, k) {
  // Scan forward with exact lengths. When a repetition first covers position k,
  // the same letter sits at position ((k - 1) mod oldLength) + 1 of the shorter tape: restart with that.
  let target = BigInt(k);
  for (;;) {
    let length = 0n;
    for (const ch of s) {
      if (ch >= 'a' && ch <= 'z') {
        length += 1n;
        if (length === target) return ch;
      } else {
        const grown = length * BigInt(ch);
        if (grown >= target) {
          target = (target - 1n) % length + 1n;
          break;
        }
        length = grown;
      }
    }
  }
}

