function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const limit = 2n ** 63n;
  const n = size === 'large' ? 100 : 2 + pick(7);
  const digitChance = size === 'large' ? [0.05, 0.15, 0.3][pick(3)] : 0.4;
  let s = letters[pick(26)];
  let length = 1n;
  while (s.length < n) {
    const d = 2 + pick(8);
    if (rand() < digitChance && length * BigInt(d) < limit) {
      s += String(d);
      length *= BigInt(d);
    } else if (length + 1n < limit) {
      // Small cases use only a few letters so repeated letters can be confused.
      s += letters[pick(size === 'large' ? 26 : 4)];
      length += 1n;
    } else {
      break;
    }
  }
  const top = Number(length < 1000000000n ? length : 1000000000n);
  const roll = rand();
  const k = roll < 0.15 ? 1 : roll < 0.3 ? top : 1 + pick(top);
  return [s, k];
}
